import{z as n,x as o,o as t,c as d,q as r,j as l,D as e,d as A,s as i,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"梯度与权重直方图","description":"","frontmatter":{"title":"梯度与权重直方图","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-gradient-weight-histograms.md","filePath":"llm/ti-gradient-weight-histograms.md","lastUpdated":1791413859000}'),m={name:"llm/ti-gradient-weight-histograms.md"};function p(h,E,g,D,u,f){const B=o("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="梯度与权重直方图" tabindex="-1">梯度与权重直方图 <a class="header-anchor" href="#梯度与权重直方图" aria-label="Permalink to &quot;梯度与权重直方图&quot;">​</a></h1><div class="epigraph"><p>标量聚合报告平均值，直方图报告形状；病常长在形状里——范数一切正常，某一层早已停止学习。</p><footer>—— 据梯度监控与大规模训练健康检查实践整理</footer></div><p><a href="/llm/ti-loss-curve-reading">上一课</a>把标量层面的判读设施搭好，但损失与全局梯度范数都是聚合数，聚合会掩盖分布的病：某层梯度常年为零、某层权重正在向少数异常值集中、更新相对权重小于一个 ULP 而纹丝不动。全局范数对这一切无感。本课写分布层面的观测：直方图记什么、多贵、形状怎么判。逐层范数的基线在<a href="/llm/grad-norm-monitoring">梯度范数监控</a>，消失与爆炸的机理在<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>，本课只补分布侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分布观测要回答三个标量答不出的问题。<strong>谁没在学</strong>：更新与权重之比长期低于权重精度的相对 ULP（bf16 约 \\(2^{-8}\\)，fp32 约 \\(2^{-24}\\)）的层，等价于没训——<a href="/llm/num-longrun-health">长期训练的健康监控</a>称之为零更新层，它在损失平台出现之前只存在于直方图里。<strong>谁在聚堆</strong>：权重或梯度的质量向少数 bin 迁移、尾部长出孤立离群柱，是<a href="/llm/num-outlier-atlas">异常值图谱</a>的早期形态，等它推高 amax 触发溢出已晚数天。<strong>谁在失衡</strong>：层间范数相差几个数量级，裁剪全局范数时实际只裁了最大那几层，其余层的学习率名义共享、实际失真。</p><p><span class="marginnote">数字实例：bf16 的相对精度约 \\(2^{-8}\\)，即约 0.4%。若某层某权重为 0.05，一次更新量小于 \\(0.05 \\times 2^{-8} \\approx 2 \\times 10^{-4}\\) 时就会被舍入吃掉、权重纹丝不动——这个层「在训练」只是名义上的，只有逐层更新比能把它揪出来。</span></p><h3 id="采集的成本纪律" tabindex="-1">采集的成本纪律 <a class="header-anchor" href="#采集的成本纪律" aria-label="Permalink to &quot;采集的成本纪律&quot;">​</a></h3><p>直方图是钩子里最贵的一类：全参数统计要求在 GPU 上归约再拷到主机，序列化与落盘都按层数乘频率增长。纪律有三条：低频采样（每 100 步量级，尖峰期临时加密）；分层抽样（固定关注层加轮换层）；存形状摘要（分位数与离群计数）而不是原始数组。采集预算仍按第一课的「全程折算」口径审，直方图不许把步时推过预算线。</p><p><span class="marginnote">最有性价比的单指标是逐层「更新与权重之比」：Adam 的 \\(\\Delta\\theta\\) 除以 \\(|\\theta|\\) 的分位数。它把学习率、精度、初始化三类问题的症状压进一个数——持续贴零是死层，持续爆表是学习率或异常值，层间差异数量级是失衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>观测配置按三层展开。<strong>每层标量</strong>（高频）：梯度范数、更新比、零更新计数，与损失同节奏落盘。<strong>分布摘要</strong>（低频）：权重、梯度、Adam 二阶矩各取 P50/P99/P999 与离群比例，加上分层抽样的直方图快照。<strong>形状告警</strong>：不设绝对阈值，设与自身基线的偏离——同层同分布的对照带，越带即查，机制与 amax 水位一致。</p><p>判读对应关系钉成表：死层查初始化与梯度通路的层间衰减诊断；聚堆查精度方案与异常值（对照<a href="/llm/num-outlier-atlas">异常值图谱</a>）；二阶矩与实际梯度长期背离查 <a href="/llm/adamw">AdamW</a> 的 \\(\\beta_2\\) 与 \\(\\epsilon\\) 配置。每条判读都要能落到「改哪个配置再验」，读不出动作的直方图只是装饰。</p>',12)),(t(),l(s,null,{default:e(()=>[i(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22GPU%20%E4%B8%8A%E6%8C%89%E5%B1%82%E7%BB%9F%E8%AE%A1%22%5D%20--%3E%20Q%5B%22%E5%88%86%E4%BD%8D%E6%95%B0%20%2B%20%E7%A6%BB%E7%BE%A4%E8%AE%A1%E6%95%B0%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%E7%9B%B4%E6%96%B9%E5%9B%BE%E5%BF%AB%E7%85%A7%22%5D%0A%20%20Q%20--%3E%20A%7B%22%E5%AF%B9%E7%85%A7%E5%B8%A6%E5%91%8A%E8%AD%A6%3F%22%7D%0A%20%20A%20--%3E%7C%E6%9B%B4%E6%96%B0%E6%AF%94%E8%B4%B4%E9%9B%B6%7C%20D1%5B%22%E6%9F%A5%E6%AD%BB%E5%B1%82%3A%20%E5%88%9D%E5%A7%8B%E5%8C%96%E4%B8%8E%E6%A2%AF%E5%BA%A6%E9%80%9A%E8%B7%AF%22%5D%0A%20%20A%20--%3E%7C%E5%B0%BE%E9%83%A8%E8%81%9A%E5%A0%86%7C%20D2%5B%22%E6%9F%A5%E7%B2%BE%E5%BA%A6%E4%B8%8E%E5%BC%82%E5%B8%B8%E5%80%BC%E5%9B%BE%E8%B0%B1%22%5D%0A%20%20A%20--%3E%7C%E5%B1%82%E9%97%B4%E5%A4%B1%E8%A1%A1%7C%20D3%5B%22%E6%9F%A5%E8%A3%81%E5%89%AA%E6%9C%89%E6%95%88%E6%80%A7%E4%B8%8E%E5%AD%A6%E4%B9%A0%E7%8E%87%22%5D%0A%20%20A%20--%3E%7C%E5%90%A6%7C%20C%5B%22%E7%BB%A7%E7%BB%AD%E4%BD%8E%E9%A2%91%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("分布观测有效的机理在于它看的是"),a("strong",null,"过程量"),A("而非结果量：损失是积分效应，等它异常，病因已存在数天；逐层更新比与形状漂移是每步都在发生的局部事件，能在后果到达损失之前报警。对照带而非绝对阈值的机理是张量尺度天然异质：嵌入与注意力输出的范数相差量级，全局阈值要么只报嵌入、要么永不触发；与自身基线比，才把「变化」从「大小」里分离。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：对照带就是「和自己的历史比」——为每层记录同分布时期的正常波动区间，新样本越出区间才告警。相当于给每层配一条个人体温基线：有人常年 36 度、有人 37 度，若用同一条全国红线，必然有人误报、有人漏报。")],-1)),(t(),l(s,null,{default:e(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E7%AC%AC%200%20%E5%A4%A9%3A%20%E6%9F%90%E5%B1%82%E5%B0%BE%E9%83%A8%E5%BC%80%E5%A7%8B%E8%81%9A%E5%A0%86%22%5D%20--%3E%20B%5B%22%E6%95%B0%E5%A4%A9%E5%90%8E%3A%20amax%20%E8%A2%AB%E7%A6%BB%E7%BE%A4%E5%80%BC%E6%8E%A8%E9%AB%98%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9B%B4%E6%99%9A%3A%20%E6%BA%A2%E5%87%BA%E4%B8%8E%E6%8D%9F%E5%A4%B1%E5%B0%96%E5%B3%B0%22%5D%0A%20%20A%20-.-%3E%7C%22%E5%AF%B9%E7%85%A7%E5%B8%A6%E6%8A%A5%E8%AD%A6%3A%20%E6%8F%90%E5%89%8D%E6%95%B0%E5%A4%A9%22%7C%20FIX%5B%22%E5%AE%9A%E5%90%91%E6%A3%80%E6%9F%A5%E8%AF%A5%E5%B1%82%E7%B2%BE%E5%BA%A6%E4%B8%8E%E5%BC%82%E5%B8%B8%E5%80%BC%22%5D%0A%20%20B%20-.-%3E%7C%22%E6%A0%87%E9%87%8F%E9%98%88%E5%80%BC%E6%8A%A5%E8%AD%A6%3A%20%E5%81%8F%E6%99%9A%22%7C%20FIX%0A%20%20C%20--%3E%20POST%5B%22%E5%8F%AA%E5%89%A9%E4%BA%8B%E5%90%8E%E5%8F%99%E4%BA%8B%3A%20%E5%9B%9E%E6%94%BE%E4%B8%8E%E5%BD%92%E6%A1%A3%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>低频采样的机理与检查点频率同构：统计是旁路，主路是训练，把旁路做重会付出整程复利。这也是为什么判读表强调「可落到动作」——低频数据天然滞后，若读它不能换来一次定向的配置变更，它就只剩事后叙事价值。</p><p><span class="marginnote">直觉类比：低频采样像体检而不是心电监护——定期抽血能追踪趋势，但若每分钟抽一次血，人就活在被抽血里了。直方图是训练的旁路体检：采样太密，主路（训练本身）被拖慢，观测就喧宾夺主了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>直方图是诊断面不是训练面：异常后怎么改（重初始化、调精度、隔离层）归数值与调试各课，本课只负责把病指出来。抽样必然有盲区——轮换层之间的病变可能漏采，关键层名单要靠历史事故反推维护。小模型上直方图的边际价值低，标量与少数层快照够用；观测设施随模型规模分档，不是越全越好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标量看聚合，直方图看形状；零更新层、尾部聚堆、层间失衡都先在分布里显形。</li><li>逐层更新与权重之比是性价比最高的单指标，贴零是死层、爆表是学习率或异常值。</li><li>采集低频、抽样、存分位数摘要，成本按全程折算，不占训练预算。</li><li>告警用自身基线对照带，不用全局绝对阈值；每条判读必须落到配置动作。</li><li>出处：据梯度监控与长期训练健康检查实践整理；机理背景见梯度消失爆炸与异常值图谱各课。</li></ul>',6))])}const c=n(m,[["render",p]]);export{_ as __pageData,c as default};
